def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', MIN_SUPPLY)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            pass

    # If no opponents, bid just enough to survive
    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Pressure signal: if someone aggressively bid close to salary, we expect competition
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Determine scarcity factor from supply
    # If supply is near our requirement, competition likely increases.
    s = float(supply)
    if s <= float(WATER_REQ) + 1.0:
        scarcity = 1.0
    elif s <= (float(WATER_REQ) + 5.0):
        scarcity = 0.7
    else:
        scarcity = 0.4

    # Baseline bid: aim to win without overspending.
    # If yesterday highest bid was high, increase slightly.
    # If our hp is low, increase to avoid no-water days.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * (0.35 + 0.25 * scarcity)
        if my_hp <= 2.0:
            base = DAILY_SALARY * (0.85 + 0.1 * scarcity)
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        base = DAILY_SALARY * (0.45 + 0.25 * scarcity)
        if my_hp <= 2.0:
            base = DAILY_SALARY * (0.65 + 0.2 * scarcity)
    else:
        base = DAILY_SALARY * (0.5 + 0.2 * scarcity)
        if my_hp <= 2.0:
            base = DAILY_SALARY * (0.75 + 0.15 * scarcity)

    # Cap bid by budget and keep within reasonable bounds
    # Also avoid bidding more than we can afford.
    bid = min(my_budget, base)

    # If budget is very low, bid proportionally to remaining budget.
    if my_budget <= DAILY_SALARY * 0.2:
        bid = my_budget

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe = DAILY_SALARY * 0.08
        return float(max(0.0, min(budget, safe)))

    prev_bids = []
    aggressive_count = 0
    zeroish_count = 0
    rich_aggressive = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 100:
                aggressive_count += 1
                if opp.get('budget', 0) >= 100:
                    rich_aggressive += 1
            if bid <= 1:
                zeroish_count += 1

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    contenders = 1 + len(alive)
    scarcity = contenders - slots

    urgent = False
    if hp <= 3 or no_water_days >= 1:
        urgent = True

    if slots >= 2:
        base = 0.0
        if urgent:
            if aggressive_count >= 1:
                base = 102.0
            else:
                base = 38.0
        else:
            if rich_aggressive >= 1:
                base = 0.0
            elif zeroish_count >= max(1, len(alive) - 1):
                base = 1.0
            else:
                base = 3.0
    else:
        if urgent:
            if prev_bids:
                base = max(108.0, max(prev_bids) + 2.0)
            else:
                base = 108.0
        else:
            if rich_aggressive >= 1:
                base = 0.0
            elif prev_bids:
                high = max(prev_bids)
                if high >= 120:
                    base = 0.0
                else:
                    base = min(95.0, high + 2.0)
            else:
                base = 12.0

    if day >= 8:
        if urgent:
            base = max(base, 110.0)
        else:
            base = max(base, 8.0)

    if hp <= 2:
        base = max(base, 120.0)
    elif hp <= 4 and no_water_days >= 1:
        base = max(base, 105.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.15
    max_spend = budget - reserve_floor
    if urgent:
        max_spend = budget
    if max_spend < 0:
        max_spend = 0.0

    bid = min(base, max_spend)
    if urgent and bid < min(budget, 35.0):
        bid = min(budget, 35.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140.0

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    bob_prev_bid = 0.0
    for opp_id, opp_data in opponents_status.items():
        if opp_id == "Bob":
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bob_prev_bid = prev['bid']
            break

    num_water_slots = int(day_context['supply'] // WATER_REQ)
    total_competitors = len(alive_opponents) + 1

    base_bid = DAILY_SALARY * 0.6

    if bob_prev_bid > 0:
        if bob_prev_bid >= DAILY_SALARY * 0.9:
            if my_status['hp'] <= 3:
                base_bid = DAILY_SALARY * 0.99
            else:
                base_bid = min(DAILY_SALARY * 0.95, bob_prev_bid + 2.0)
        elif bob_prev_bid >= DAILY_SALARY * 0.7:
            base_bid = min(DAILY_SALARY * 0.85, bob_prev_bid + 3.0)
        elif bob_prev_bid >= DAILY_SALARY * 0.4:
            base_bid = max(base_bid, bob_prev_bid + 1.0)
            base_bid = min(base_bid, DAILY_SALARY * 0.7)

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.99
    elif my_status['hp'] <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)

    if num_water_slots == 0:
        if my_status['hp'] <= 3:
            base_bid = DAILY_SALARY * 0.99
        else:
            base_bid = DAILY_SALARY * 0.1
    elif num_water_slots < total_competitors:
        if my_status['hp'] <= 5:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.75)

    final_bid = min(my_status['budget'], base_bid)

    return max(1.0, final_bid)
